# helpers
def write_csv(name, fields, rows):
    with open(DATA/name,'w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore'); w.writeheader()
        for r in rows: w.writerow({k:r.get(k,'NULL') if r.get(k,'NULL') not in [None,''] else 'NULL' for k in fields})

def feat(fid, geom, props): return {'type':'Feature','id':fid,'geometry':geom,'properties':props}

def point(lon,lat): return {'type':'Point','coordinates':[lon,lat]}

src_rows=[]
for s in sources:
    sid,author,title,year,stype,lang,url,pages,access,tier,notes=s
    src_rows.append({'source_id':sid,'author':author,'title':title,'publication_year':year,'publisher':author,'source_type':stype,'language':lang,'url':url,'archive_reference':pages,'pages':pages,'access_date':access,'reliability_tier':tier,'notes':notes})
write_csv('sources.csv',['source_id','author','title','publication_year','publisher','source_type','language','url','archive_reference','pages','access_date','reliability_tier','notes'],src_rows)

