# GeoJSON layers
sett_features=[]
for r in place_rows:
    try:
        lon=float(r['longitude']); lat=float(r['latitude'])
        geom=point(lon,lat)
    except: geom=None
    sett_features.append(feat(r['place_id'],geom,{k:v for k,v in r.items() if k not in ['longitude','latitude']}))
json.dump({'type':'FeatureCollection','name':'rumelia_atlas_pilot_settlements','features':sett_features},open(GEO/'settlements.geojson','w',encoding='utf-8'),ensure_ascii=False,indent=2)
her_features=[]
for r in heritage_norm:
    her_features.append(feat(r['heritage_id'],point(float(r['longitude']),float(r['latitude'])),r))
json.dump({'type':'FeatureCollection','name':'rumelia_atlas_pilot_heritage','features':her_features},open(GEO/'heritage.geojson','w',encoding='utf-8'),ensure_ascii=False,indent=2)
# Null geometry for region claims: no boundary was extracted, so no invented polygons.
regions=[('REG-001','Polog','cultural_region','core_area','NULL','NULL','SRC-011','Regional label; geometry pending source map extraction.'),('REG-002','Kosovo / Metohija','cultural_region','approximate_extent','NULL','NULL','SRC-013','Fluid historical-cultural frame; no political boundary asserted.'),('REG-003','Skopje–Tetovo–Prizren pilot corridor','research_scope','approximate_extent','NULL','NULL','SRC-032','Research scope, not a historical political region or canonical centerline.')]
json.dump({'type':'FeatureCollection','name':'rumelia_atlas_pilot_cultural_regions','features':[feat(a,None,{'region_id':a,'name':b,'type':c,'geometry_precision':d,'valid_from':e,'valid_to':f,'source_id':g,'notes':h}) for a,b,c,d,e,f,g,h in regions]},open(GEO/'cultural_regions.geojson','w',encoding='utf-8'),ensure_ascii=False,indent=2)
# Migration claims with null geometry because no source-supported line geometry was extracted.
json.dump({'type':'FeatureCollection','name':'rumelia_atlas_pilot_migrations','features':[feat(r[0],None,{'migration_id':r[0],'origin_place_id':r[1],'destination_place_id':r[2],'start_year':r[3],'end_year':r[4],'community':r[5],'estimated_population':r[6],'migration_type':r[7],'cause':r[8],'source_id':r[9],'confidence':r[10],'notes':r[11]}) for r in migrations]},open(GEO/'migrations.geojson','w',encoding='utf-8'),ensure_ascii=False,indent=2)

